/** CSS-012 fixture: the mock daily report with a realistic short operator name in the "generated by" line. Synthetic only. */
import { reportEnvelope } from './mocks';

export function dailyReportBy(name: string) {
  const j = JSON.parse(JSON.stringify(reportEnvelope('daily'))) as { data: { header: { generatedBy: string } } };
  j.data.header.generatedBy = name;
  return j;
}
